#!/bin/bash
# Prints the three IP addresses that appear most often in access.log,
# most frequent first. Ties are broken by first appearance in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '
{
    ip = $1
    if (!(ip in count)) {
        order[ip] = NR
    }
    count[ip]++
}
END {
    n = 0
    for (ip in count) {
        n++
        ips[n] = ip
    }
    for (i = 1; i <= n; i++) {
        for (j = i + 1; j <= n; j++) {
            if (count[ips[j]] > count[ips[i]] ||
                (count[ips[j]] == count[ips[i]] && order[ips[j]] < order[ips[i]])) {
                tmp = ips[i]; ips[i] = ips[j]; ips[j] = tmp
            }
        }
    }
    limit = (n < 3) ? n : 3
    for (i = 1; i <= limit; i++) {
        print ips[i]
    }
}
' access.log
